export interface MovingAverageOptions {
  period: number;
}

export class SimpleMovingAverage {
  private readonly period: number;
  private window: number[] = [];
  private sum: number = 0;

  constructor(period: number) {
    if (period <= 0) throw new Error("Period must be greater than 0");
    this.period = period;
  }

  public update(value: number): number {
    this.window.push(value);
    this.sum += value;
    if (this.window.length > this.period) {
      const removed = this.window.shift()!;
      this.sum -= removed;
    }
    return this.sum / this.window.length;
  }

  public get value(): number | null {
    return this.window.length === 0 ? null : this.sum / this.window.length;
  }

  public isFull(): boolean {
    return this.window.length === this.period;
  }
}

export class ExponentialMovingAverage {
  private readonly period: number;
  private readonly k: number;
  private currentEma: number | null = null;

  constructor(period: number) {
    if (period <= 0) throw new Error("Period must be greater than 0");
    this.period = period;
    this.k = 2 / (period + 1);
  }

  public update(value: number): number {
    if (this.currentEma === null) {
      this.currentEma = value;
    } else {
      this.currentEma = value * this.k + this.currentEma * (1 - this.k);
    }
    return this.currentEma;
  }

  public get value(): number | null {
    return this.currentEma;
  }
}

export function calculateSMA(data: readonly number[], period: number): number[] {
  const sma = new SimpleMovingAverage(period);
  return data.map((val) => sma.update(val));
}

export function calculateEMA(data: readonly number[], period: number): number[] {
  const ema = new ExponentialMovingAverage(period);
  return data.map((val) => ema.update(val));
}
